/// Computes the arithmetic sum of the first `n` natural numbers.
/// 
/// # Arguments
/// 
/// * `n` - A non-negative 64-bit unsigned integer representing the upper limit of the sum.
/// 
/// # Returns
/// 
/// The sum of the first `n` natural numbers as a 64-bit unsigned integer.
fn compute_arith_sum(n: u64) -> u64 {
    let mut sum = 0;
    let mut index = 1;

    // Loop until index exceeds n
    while index <= n {
        // Check if adding the next number keeps the sum below 10,000
        if sum + index >= 10_000 {
            break; // Stop if the next addition would exceed the limit
        }
        sum += index; // Add the current index to the sum
        index += 1;   // Move to the next natural number
    }

    sum // Return the computed sum
}

fn main() {
    let n: u64 = 10; // Example input
    let result = compute_arith_sum(n);
    println!("The sum of the first {} natural numbers is: {}", n, result);
}